        }
    } catch (e) {
        // Variable does not exist → ignore it
    }
}

current_pnr = {
    ...current_pnr,
    outcome,
    proceedHandling,
    new_flights,
    ...dynamicValues
}

let selected_pnrs_customer_action = transforms.selected_pnrs_customer_action || [];

const last = selected_pnrs_customer_action[selected_pnrs_customer_action.length - 1];
if (last !== current_pnr) {
  selected_pnrs_customer_action.push(current_pnr);
}

